def build_pp_document(markdown: str, out_name: str = "document") -> str:
    """Generate a Purely Plant bilingual Macedonian|English controlled .docx (SOP / Annex / form / report) from bilingual Markdown, in the house style. Saves to /root/.letta/pp-out; returns JSON {ok, verify, path, bytes}.

    Args:
        markdown (str): bilingual Markdown - a <!--HEADERDATA ...--> block (mk_title,en_title,code,version,doctype,parent,orient) then sections; '|||' separates the Macedonian and English halves; '[[TABLE]]'/'[[FORM]]' blocks with '~~' inside cells.
        out_name (str): output base file name without extension. Optional; defaults to 'document'.
    """
    import os, sys, io, json, tempfile, contextlib, traceback, zipfile
    LIBS="/root/.letta/pp-libs"
    if LIBS not in sys.path: sys.path.insert(0, LIBS)
    SUITE=os.environ.get("PP_SUITE_DIR","/root/.letta/pp-document-suite"); S=os.path.join(SUITE,"scripts")
    if S not in sys.path: sys.path.insert(0,S)
    OUT="/root/.letta/pp-out"; os.makedirs(OUT,exist_ok=True)
    out=os.path.join(OUT,(out_name or "document")+".docx")
    with tempfile.NamedTemporaryFile("w",suffix=".md",delete=False,encoding="utf-8") as f:
        f.write(markdown); src=f.name
    try:
        import importlib, build_from_md; importlib.reload(build_from_md); build_from_md.main(src,out)
    except Exception:
        os.unlink(src); return json.dumps({"ok":False,"err":traceback.format_exc()[-800:]})
    os.unlink(src)
    verify=""
    try:
        import pp_verify, importlib; importlib.reload(pp_verify)
        buf=io.StringIO(); oa=sys.argv; sys.argv=["pp_verify",out]
        try:
            with contextlib.redirect_stdout(buf): pp_verify.main()
        except SystemExit: pass
        finally: sys.argv=oa
        verify=buf.getvalue().strip()
    except Exception as e: verify="verify-error: "+str(e)[:150]
    ok=os.path.exists(out) and zipfile.is_zipfile(out) and "RESULT: PASS" in verify
    return json.dumps({"ok":ok,"verify":verify,"path":out,"bytes":(os.path.getsize(out) if os.path.exists(out) else 0)})

def fetch_pp_document(path: str) -> str:
    """Return a generated .docx as base64 so it can be downloaded/attached.

    Args:
        path (str): absolute path of a .docx produced by build_pp_document (under /root/.letta/pp-out).
    """
    import os, base64, json
    if not os.path.exists(path): return json.dumps({"ok":False,"err":"not found: "+path})
    return json.dumps({"ok":True,"name":os.path.basename(path),"bytes":os.path.getsize(path),
                       "base64":base64.b64encode(open(path,"rb").read()).decode()})
